def dedupe_stable(items):
    seen = set()
    output = []
    for item in items:
        if item not in seen:
            seen.add(item)
            output.append(item)
    return output

rows = ['b', 'a', 'b', 'c', 'a']
print(dedupe_stable(rows))
print(sorted(set(rows)))

def group_anagrams(words):
    groups = {}
    for word in words:
        key = ''.join(sorted(word))
        groups.setdefault(key, []).append(word)
    return list(groups.values())

print(group_anagrams(['eat', 'tea', 'tan', 'ate']))

